SET search_path TO "core";
CREATE TABLE "QualifiedRequirement" ("id" TEXT NOT NULL,"buyerProfileId" TEXT,"buyerContactId" TEXT,"sourceSignalId" TEXT,"organizationId" TEXT,"source" "RequirementSource" NOT NULL DEFAULT 'AI_COMPOSER',"sourceContext" JSONB,"status" "RequirementStatus" NOT NULL DEFAULT 'DRAFT',"product" TEXT NOT NULL,"market" TEXT NOT NULL,"quantity" DECIMAL(18,4),"unit" TEXT,"containerCount" INTEGER,"septlionScale" TEXT,"deliveryCountry" TEXT,"deliveryPort" TEXT,"destinationCode" TEXT,"incoterm" TEXT,"paymentPreference" TEXT,"targetPrice" DECIMAL(18,4),"currency" TEXT,"requiredDate" TIMESTAMP(3),"knownFacts" JSONB NOT NULL,"inferredFacts" JSONB,"fieldStates" JSONB,"criticalMissing" JSONB,"productConfiguration" JSONB,"specifications" JSONB,"packing" JSONB,"compliance" JSONB,"confidence" INTEGER NOT NULL DEFAULT 0,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "QualifiedRequirement_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Opportunity" ("id" TEXT NOT NULL,"reference" TEXT NOT NULL,"status" "OpportunityStatus" NOT NULL DEFAULT 'DISCOVERED',"sourceSignalId" TEXT,"buyerProfileId" TEXT,"requirementId" TEXT,"rfqId" TEXT,"title" TEXT NOT NULL,"market" TEXT NOT NULL,"product" TEXT NOT NULL,"commercialValue" DECIMAL(18,2),"currency" TEXT,"nextAction" TEXT,"nextActionAt" TIMESTAMP(3),"evidence" JSONB,"risk" JSONB,"economics" JSONB,"humanApproval" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Opportunity_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AgentRun" ("id" TEXT NOT NULL,"opportunityId" TEXT,"agentType" TEXT NOT NULL,"runtime" TEXT,"status" "AgentRunStatus" NOT NULL DEFAULT 'QUEUED',"input" JSONB NOT NULL,"output" JSONB,"evidence" JSONB,"error" TEXT,"startedAt" TIMESTAMP(3),"finishedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "AgentRun_pkey" PRIMARY KEY ("id"));
CREATE TABLE "HumanApproval" ("id" TEXT NOT NULL,"opportunityId" TEXT NOT NULL,"action" "ApprovalAction" NOT NULL,"decision" "ApprovalDecision" NOT NULL DEFAULT 'PENDING',"title" TEXT NOT NULL,"summary" TEXT,"payload" JSONB,"decidedBy" TEXT,"decidedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "HumanApproval_pkey" PRIMARY KEY ("id"));
CREATE TABLE "SupplyCandidate" ("id" TEXT NOT NULL,"opportunityId" TEXT NOT NULL,"supplierOrgId" TEXT,"supplierName" TEXT NOT NULL,"country" TEXT,"source" TEXT,"sourceUrl" TEXT,"capability" JSONB,"compliance" JSONB,"commercial" JSONB,"logistics" JSONB,"confidence" INTEGER NOT NULL DEFAULT 0,"verified" BOOLEAN NOT NULL DEFAULT false,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "SupplyCandidate_pkey" PRIMARY KEY ("id"));
CREATE TABLE "DealDraft" ("id" TEXT NOT NULL,"opportunityId" TEXT NOT NULL,"version" INTEGER NOT NULL DEFAULT 1,"currency" TEXT NOT NULL DEFAULT 'USD',"exWorks" DECIMAL(18,2),"freight" DECIMAL(18,2),"qc" DECIMAL(18,2),"documents" DECIMAL(18,2),"duties" DECIMAL(18,2),"riskReserve" DECIMAL(18,2),"landedCost" DECIMAL(18,2),"grossMarginPct" DECIMAL(8,4),"offerPrice" DECIMAL(18,2),"assumptions" JSONB,"status" TEXT NOT NULL DEFAULT 'DRAFT',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "DealDraft_pkey" PRIMARY KEY ("id"));
CREATE TABLE "CommercialLock" ("id" TEXT NOT NULL,"quoteId" TEXT,"quoteRevisionId" TEXT,"offerId" TEXT,"offerRevisionId" TEXT,"orderIntentId" TEXT,"buyerOrgId" TEXT NOT NULL,"supplierOrgId" TEXT NOT NULL,"version" INTEGER NOT NULL DEFAULT 1,"snapshot" JSONB NOT NULL,"snapshotHash" TEXT NOT NULL,"lockedByUserId" TEXT,"lockedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "CommercialLock_pkey" PRIMARY KEY ("id"));
CREATE TABLE "TradeTransaction" ("id" TEXT NOT NULL,"reference" TEXT NOT NULL,"commercialLockId" TEXT NOT NULL,"buyerOrgId" TEXT NOT NULL,"supplierOrgId" TEXT NOT NULL,"status" "TradeTransactionStatus" NOT NULL DEFAULT 'PENDING_COMMIT',"version" INTEGER NOT NULL DEFAULT 1,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "TradeTransaction_pkey" PRIMARY KEY ("id"));
CREATE TABLE "TradeEvent" ("id" TEXT NOT NULL,"transactionId" TEXT NOT NULL,"sequence" INTEGER NOT NULL,"type" TEXT NOT NULL,"visibility" "TradeEventVisibility" NOT NULL DEFAULT 'INTERNAL',"actorOrgId" TEXT,"actorUserId" TEXT,"occurredAt" TIMESTAMP(3) NOT NULL,"payload" JSONB NOT NULL,"evidence" JSONB,"idempotencyKey" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "TradeEvent_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ChangeOrder" ("id" TEXT NOT NULL,"commercialLockId" TEXT NOT NULL,"number" INTEGER NOT NULL,"status" "ChangeOrderStatus" NOT NULL DEFAULT 'PROPOSED',"requestedByOrgId" TEXT NOT NULL,"requestedByUserId" TEXT,"reason" TEXT NOT NULL,"patch" JSONB NOT NULL,"impact" JSONB,"approvedByUserId" TEXT,"approvedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "ChangeOrder_pkey" PRIMARY KEY ("id"));
CREATE TABLE "SeptlionOffer" ("id" TEXT NOT NULL,"requirementId" TEXT NOT NULL,"rfqId" TEXT NOT NULL,"buyerOrgId" TEXT NOT NULL,"operatorOrgId" TEXT NOT NULL,"status" "SeptlionOfferStatus" NOT NULL DEFAULT 'DRAFT',"currentRevision" INTEGER NOT NULL DEFAULT 0,"currency" TEXT NOT NULL DEFAULT 'USD',"validUntil" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "SeptlionOffer_pkey" PRIMARY KEY ("id"));
CREATE TABLE "SeptlionOfferRevision" ("id" TEXT NOT NULL,"offerId" TEXT NOT NULL,"revisionNo" INTEGER NOT NULL,"status" "SeptlionOfferRevisionStatus" NOT NULL DEFAULT 'DRAFT',"snapshot" JSONB NOT NULL,"snapshotHash" TEXT NOT NULL,"issuedById" TEXT,"issuedAt" TIMESTAMP(3),"acceptedById" TEXT,"acceptedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "SeptlionOfferRevision_pkey" PRIMARY KEY ("id"));
CREATE TABLE "TradeMilestone" ("id" TEXT NOT NULL,"transactionId" TEXT NOT NULL,"code" TEXT NOT NULL,"label" TEXT NOT NULL,"sequence" INTEGER NOT NULL,"status" "MilestoneStatus" NOT NULL DEFAULT 'PENDING',"buyerVisible" BOOLEAN NOT NULL DEFAULT true,"targetAt" TIMESTAMP(3),"startedAt" TIMESTAMP(3),"completedAt" TIMESTAMP(3),"evidence" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "TradeMilestone_pkey" PRIMARY KEY ("id"));
CREATE TABLE "TradeReceipt" ("id" TEXT NOT NULL,"transactionId" TEXT NOT NULL,"status" "ReceiptStatus" NOT NULL DEFAULT 'PENDING',"confirmedById" TEXT,"confirmedAt" TIMESTAMP(3),"notes" TEXT,"evidence" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "TradeReceipt_pkey" PRIMARY KEY ("id"));
CREATE TABLE "TradeClaim" ("id" TEXT NOT NULL,"transactionId" TEXT NOT NULL,"reference" TEXT NOT NULL,"status" "ClaimStatus" NOT NULL DEFAULT 'OPEN',"category" TEXT NOT NULL,"description" TEXT NOT NULL,"requestedResolution" TEXT,"evidence" JSONB,"resolution" JSONB,"openedById" TEXT,"resolvedById" TEXT,"resolvedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "TradeClaim_pkey" PRIMARY KEY ("id"));
